// Copies the lite, single-threaded Stockfish WASM build from node_modules into
// public/engine/ so Vite serves it as a static worker. The output is gitignored
// and regenerated by `postinstall` and `prebuild`.
import { copyFileSync, existsSync, mkdirSync, readdirSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const sourceDir = join(root, 'node_modules', 'stockfish', 'bin')
const targetDir = join(root, 'public', 'engine')

if (!existsSync(sourceDir)) {
  console.warn('[copy-stockfish] node_modules/stockfish/bin not found; skipping.')
  process.exit(0)
}

const files = readdirSync(sourceDir)
const js = files.find((name) => /^stockfish-.*lite-single\.js$/.test(name))
const wasm = files.find((name) => /^stockfish-.*lite-single\.wasm$/.test(name))

if (!js || !wasm) {
  console.error('[copy-stockfish] lite single-threaded engine files not found in', sourceDir)
  process.exit(1)
}

mkdirSync(targetDir, { recursive: true })
// The engine looks for a .wasm file named like the worker script, so both are
// renamed together.
copyFileSync(join(sourceDir, js), join(targetDir, 'stockfish.js'))
copyFileSync(join(sourceDir, wasm), join(targetDir, 'stockfish.wasm'))
console.log(`[copy-stockfish] ${js} + ${wasm} -> public/engine/stockfish.{js,wasm}`)
